from typing import TypeVar, Callable, List

T = TypeVar('T')

def merge_sort(arr: List[T], key: Callable[[T], any] = None, reverse: bool = False) -> List[T]:
    """EGRR_PATTERN: Merge sort with custom key and reverse option.

    Stable sort with O(n log n) time complexity.
    Handles empty arrays and single elements.
    """
    if len(arr) <= 1:
        return arr.copy()

    key = key or (lambda x: x)

    def merge(left: List[T], right: List[T]) -> List[T]:
        result = []
        i = j = 0

        while i < len(left) and j < len(right):
            left_key = key(left[i])
            right_key = key(right[j])

            compare = left_key <= right_key if not reverse else left_key >= right_key

            if compare:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1

        result.extend(left[i:])
        result.extend(right[j:])
        return result

    mid = len(arr) // 2
    left = merge_sort(arr[:mid], key, reverse)
    right = merge_sort(arr[mid:], key, reverse)

    return merge(left, right)

def quick_sort(arr: List[T], key: Callable[[T], any] = None) -> List[T]:
    """EGRR_PATTERN: Quick sort with median-of-three pivot.

    Handles edge cases and uses median-of-three for better pivot selection.
    """
    if len(arr) <= 1:
        return arr.copy()

    key = key or (lambda x: x)
    arr = arr.copy()

    def partition(low: int, high: int) -> int:
        # Median-of-three pivot selection
        mid = (low + high) // 2
        if key(arr[low]) > key(arr[mid]):
            arr[low], arr[mid] = arr[mid], arr[low]
        if key(arr[mid]) > key(arr[high]):
            arr[mid], arr[high] = arr[high], arr[mid]
        if key(arr[low]) > key(arr[mid]):
            arr[low], arr[mid] = arr[mid], arr[low]

        arr[mid], arr[high] = arr[high], arr[mid]
        pivot = key(arr[high])

        i = low - 1
        for j in range(low, high):
            if key(arr[j]) <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]

        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    def sort(low: int, high: int):
        if low < high:
            pi = partition(low, high)
            sort(low, pi - 1)
            sort(pi + 1, high)

    sort(0, len(arr) - 1)
    return arr
